        self.current_frame = 0
        self.is_frame_complete = False
        self.frame_rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("Invalid number of pins")

        self.rolls.append(pins)
        self.frame_rolls.append(pins)

        # Check if we're at the end of a frame
        if self.is_frame_complete:
            self.current_frame += 1
            self.frame_rolls = [pins]
            self.is_frame_complete = False
        else:
            # Check if this completes the frame
            if self.current_frame < 9:  # First 9 frames
                if len(self.frame_rolls) == 2:
                    self.is_frame_complete = True
                elif self.frame_rolls[0] == 10:  # Strike
                    self.is_frame_complete = True
            else:  # Tenth frame
                if len(self.frame_rolls) == 3:  # Strike with two bonus rolls
                    self.is_frame_complete = True
                elif len(self.frame_rolls) == 2 and sum(self.frame_rolls) < 10:  # Open frame
                    self.is_frame_complete = True
                elif len(self.frame_rolls) == 2 and sum(self.frame_rolls) == 10:  # Spare
                    self.is_frame_complete = True

    def score(self):
        total = 0
        roll_index = 0

        for frame in range(10):
            if roll_index >= len(self.rolls):
                break

            if self.is_strike(roll_index):
                total += 10 + self.strike_bonus(roll_index)
                roll_index += 1
            else:
                frame_pins = self.frame_pins(roll_index)
                if self.is_spare(roll_index):
                    total += 10 + self.rolls[roll_index + 2]
                else:
                    total += frame_pins
                roll_index += 2

        return total

    def is_strike(self, roll_index):
        return self.rolls[roll_index] == 10

    def is_spare(self, roll_index):
        return self.rolls[roll_index] + self.rolls[roll_index + 1] == 10

    def frame_pins(self, roll_index):
        return self.rolls[roll_index] + self.rolls[roll_index + 1]

    def strike_bonus(self, roll_index):
        bonus = self.rolls[roll_index + 1]
        if self.rolls[roll_index + 1] == 10 and roll_index + 2 < len(self.rolls):
            bonus += self.rolls[roll_index + 2]
        return bonus
