import math

class Rational:
    def __init__(self, numer, denom):
        # Handle zero denominator
        if denom == 0:
            raise ValueError("Denominator cannot be zero")

        # Reduce to lowest terms and ensure standard form
        gcd = math.gcd(abs(numer), abs(denom))
        self.numer = numer // gcd
        self.denom = denom // gcd

        # Ensure standard form (positive denominator)
        if self.denom < 0:
            self.numer = -self.numer
            self.denom = -self.denom

    def __eq__(self, other):
        return self.numer == other.numer and self.denom == other.denom

    def __repr__(self):
        return f'{self.numer}/{self.denom}'

    def __add__(self, other):
        numer = self.numer * other.denom + other.numer * self.denom
        denom = self.denom * other.denom
        return Rational(numer, denom)

    def __sub__(self, other):
        numer = self.numer * other.denom - other.numer * self.denom
        denom = self.denom * other.denom
        return Rational(numer, denom)

    def __mul__(self, other):
        numer = self.numer * other.numer
        denom = self.denom * other.denom
        return Rational(numer, denom)

    def __truediv__(self, other):
        if other.numer == 0:
            raise ZeroDivisionError("Division by zero")
        numer = self.numer * other.denom
        denom = self.denom * other.numer
        return Rational(numer, denom)

    def __abs__(self):
        return Rational(abs(self.numer), self.denom)

    def __pow__(self, power):
        if isinstance(power, int):
            if power >= 0:
                return Rational(self.numer ** power, self.denom ** power)
            else:
                # For negative powers, swap numerator and denominator
                abs_power = abs(power)
                return Rational(self.denom ** abs_power, self.numer ** abs_power)
        elif isinstance(power, float):
            # For real number powers, compute (a^x)/(b^x)
            return (self.numer ** power) / (self.denom ** power)
        else:
            raise TypeError("Power must be an integer or float")

    def __rpow__(self, base):
        # x^(a/b) = root(x^a, b)
        return (base ** self.numer) ** (1 / self.denom)
```

