```python
from collections import deque, defaultdict

class RelativeDistance:
    def __init__(self, family_tree):
        # Build a graph representation of the family tree
        self.graph = defaultdict(list)

        # Add parent-child relationships
        for parent, children in family_tree.items():
            for child in children:
                # Add bidirectional edges for parent-child relationships
                self.graph[parent].append(child)
                self.graph[child].append(parent)

    def degree_of_separation(self, person_a, person_b):
        # If both people are the same, degree of separation is 0
        if person_a == person_b:
            return 0

        # Use BFS to find shortest path
        queue = deque([(person_a, 0)])
        visited = {person_a}

        while queue:
            current_person, distance = queue.popleft()

            # Check all neighbors (parents and children)
            for neighbor in self.graph[current_person]:
                if neighbor == person_b:
                    return distance + 1

                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))

        # No path found
        return -1
```

