APPROACH: I'll implement a reactive system with InputCell and ComputeCell classes that handle value propagation and callback notifications. The key is to track dependencies, propagate changes through the dependency graph, and notify callbacks when values change.

```python
class InputCell:
    def __init__(self, initial_value):
        self.value = initial_value
        self.callbacks = []
        self.dependents = []

    def set_value(self, new_value):
        old_value = self.value
        self.value = new_value
        # Notify all dependents about the change
        for dependent in self.dependents:
            dependent.update()
        # Notify callbacks if value changed
        if old_value != new_value:
            for callback in self.callbacks:
                callback(new_value)


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self.inputs = inputs
        self.compute_function = compute_function
        self.value = None
        self.callbacks = []
        self.dependents = []
        self._update_value()
        # Register this cell as dependent of all input cells
        for input_cell in inputs:
            input_cell.dependents.append(self)

    def _update_value(self):
        # Get current values from all input cells
        input_values = [input_cell.value for input_cell in self.inputs]
        # Compute new value
        new_value = self.compute_function(input_values)
        # Store old value for comparison
        old_value = self.value
        self.value = new_value
        # Notify callbacks if value changed
        if old_value != new_value:
            for callback in self.callbacks:
                callback(new_value)

    def update(self):
        # Update this cell's value based on inputs
        self._update_value()

    def add_callback(self, callback):
        self.callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self.callbacks:
            self.callbacks.remove(callback)
```

