class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y


class WordSearch:
    def __init__(self, puzzle):
        self.puzzle = puzzle
        self.height = len(puzzle)
        self.width = len(puzzle[0]) if puzzle else 0

    def search(self, word):
        if not word or not self.puzzle:
            return None

        # Define all 8 directions: right, left, down, up, and 4 diagonals
        directions = [
            (0, 1),   # right
            (0, -1),  # left
            (1, 0),   # down
            (-1, 0),  # up
            (1, 1),   # down-right
            (1, -1),  # down-left
            (-1, 1),  # up-right
            (-1, -1)  # up-left
        ]

        # Try each cell as a starting point
        for y in range(self.height):
            for x in range(self.width):
                # Try each direction from this starting point
                for dx, dy in directions:
                    if self._check_word_at_position(word, x, y, dx, dy):
                        # Return start and end points
                        start_point = Point(x, y)
                        end_x = x + (len(word) - 1) * dx
                        end_y = y + (len(word) - 1) * dy
                        end_point = Point(end_x, end_y)
                        return (start_point, end_point)

        return None

    def _check_word_at_position(self, word, start_x, start_y, dx, dy):
        """Check if word exists starting at position (start_x, start_y) in direction (dx, dy)"""
        for i, char in enumerate(word):
            x = start_x + i * dx
            y = start_y + i * dy

            # Check bounds
            if x < 0 or x >= self.width or y < 0 or y >= self.height:
                return False

            # Check character match
            if self.puzzle[y][x] != char:
                return False

        return True
```

