class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other


def parse(input_string):
    if not input_string:
        return None

    # Remove the outer parentheses
    if input_string.startswith('(') and input_string.endswith(')'):
        input_string = input_string[1:-1]

    # Parse the root node
    root = SgfTree()
    current_node = root
    stack = []

    i = 0
    while i < len(input_string):
        if input_string[i] == ';':
            # Start of a new node
            if current_node is not root:
                stack.append(current_node)
            current_node = SgfTree()
            i += 1
        elif input_string[i] == '(':
            # Start of a child node
            # Find the matching closing parenthesis
            paren_count = 1
            j = i + 1
            while j < len(input_string) and paren_count > 0:
                if input_string[j] == '(':
                    paren_count += 1
                elif input_string[j] == ')':
                    paren_count -= 1
                j += 1

            # Parse the child node
            child_string = input_string[i:j]
            child_node = parse(child_string)
            if child_node:
                current_node.children.append(child_node)

            i = j
        elif input_string[i] == ')':
            # End of current node
            if stack:
                parent = stack.pop()
                parent.children.append(current_node)
                current_node = parent
            i += 1
        elif input_string[i] == '[':
            # Parse property
            # Find the matching closing bracket
            j = i + 1
            while j < len(input_string) and input_string[j] != ']':
                j += 1

            # Extract the property value
            value = input_string[i+1:j]
            # Process escape sequences
            value = process_escape_sequences(value)

            # Find the property key (before the first '[')
            key_start = i - 1
            while key_start >= 0 and input_string[key_start] != ';':
                key_start -= 1
            key_start += 1

            # Find the key
            key_end = i
            while key_start < key_end and input_string[key_start] != '[':
                key_start += 1
            key = input_string[key_start:i]

            # Add property to current node
            if key not in current_node.properties:
                current_node.properties[key] = []
            current_node.properties[key].append(value)

            i = j + 1
        else:
            i += 1

    # If we have a stack, we need to handle the remaining nodes
    while stack:
        parent = stack.pop()
        parent.children.append(current_node)
        current_node = parent

    return root


def process_escape_sequences(value):
    """Process escape sequences in SGF text values"""
    result = []
    i = 0
    while i < len(value):
        if value[i] == '\\':
            # Check if the next character is a whitespace
            if i + 1 < len(value) and value[i + 1] in ' \t\n':
                # Skip the newline or whitespace
                if value[i + 1] != '\n':
                    result.append(' ')
                i += 2
            else:
                # Add the next character as-is
                if i + 1 < len(value):
                    result.append(value[i + 1])
                    i += 2
                else:
                    i += 1
        else:
            # Handle whitespace conversion
            if value[i] in ' \t':
                result.append(' ')
            else:
                result.append(value[i])
            i += 1

    # Remove newlines that come immediately after a backslash
    final_result = []
    i = 0
    while i < len(result):
        if i > 0 and result[i-1] == '\\' and result[i] == '\n':
            # Skip the newline
            i += 1
        else:
            final_result.append(result[i])
            i += 1

    return ''.join(final_result)
