from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        # Find the node with the given label
        node = self._find_node(from_node)
        if node is None:
            raise ValueError("Node not found")

        # Create a new tree with the node as root
        return self._rebuild_tree(node, None)

    def _find_node(self, label):
        # Helper method to find a node with the given label
        if self.label == label:
            return self

        for child in self.children:
            result = child._find_node(label)
            if result is not None:
                return result

        return None

    def _rebuild_tree(self, node, parent):
        # Helper method to rebuild the tree with a new root
        # Create a new tree node with the same label
        new_children = []

        # Add all children except the parent
        for child in node.children:
            if child != parent:
                new_children.append(self._rebuild_tree(child, node))

        # If this is not the original root, add the parent as a child
        if parent is not None:
            new_children.append(self._rebuild_tree(parent, None))

        return Tree(node.label, new_children)

    def path_to(self, from_node, to_node):
        # Find paths from from_node to to_node
        # First, get the tree rooted at from_node
        try:
            tree_from = self.from_pov(from_node)
        except ValueError:
            return []

        # Find the path from the root to to_node
        path = []
        if not self._find_path(tree_from, to_node, path):
            return []

        return path

    def _find_path(self, node, target, path):
        # Helper method to find a path from node to target
        path.append(node.label)

        if node.label == target:
            return True

        for child in node.children:
            if self._find_path(child, target, path):
                return True

        path.pop()
        return False
